const tokenPattern = /[\p{L}]+(?:[-’'][\p{L}]+)*/gu;
const normalize = value => value.normalize("NFC").toLocaleLowerCase("pt-BR");
function matchCase(source, target) {
  if (source.length > 1 && source === source.toLocaleUpperCase("pt-BR")) return target.toLocaleUpperCase("en-US");
  if (source[0] === source[0]?.toLocaleUpperCase("pt-BR")) return target[0]?.toLocaleUpperCase("en-US") + target.slice(1);
  return target;
}
const inlinePhraseTargets = new Map(inlinePhrases.map(([source,target]) => [normalize(source), target]));
const inlinePhrasePattern = new RegExp(inlinePhrases.map(([source]) => source.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|"),"gi");
